#include "abc/core.hpp"
#include "../src/file_encoding.hpp"
#include "../src/text_file.hpp"
#include "../src/file_reader.hpp"
#include <filesystem>
#include <fstream>
#include <iostream>
#include <sstream>
#include <chrono>
namespace {
std::uint64_t checks=0,failures=0;
void check(bool ok,std::string_view label){++checks;if(!ok){++failures;if(failures<=15)std::cerr<<"FAIL "<<label<<'\n';}}
struct Reader{
 std::ifstream file;explicit Reader(const std::filesystem::path& p):file(p,std::ios::binary){if(!file)throw std::runtime_error("Missing UTF7 reference");}
 unsigned byte(){int n=file.get();if(n<0)throw std::runtime_error("Truncated UTF7 reference");return static_cast<unsigned char>(n);}
 unsigned word(){auto a=byte();return a|(byte()<<8);}
 unsigned number(){auto a=word();return a|(word()<<16);}
 std::string bytes(unsigned n){std::string s;for(unsigned k=0;k<n;++k)s+=static_cast<char>(byte());return s;}
 std::string text(){unsigned n=0,s=0,b;do{b=byte();n|=(b&127)<<s;s+=7;if(s>28)throw std::runtime_error("Invalid length");}while(b&128);return bytes(n);}
 std::pair<std::u16string,bool> result(){auto flags=byte();std::u16string value;for(unsigned n=0;n<(flags&127);++n)value+=static_cast<char16_t>(word());return {value,(flags&128)!=0};}
};
const abc::TextEncoding normal{abc::TextEncodingKind::utf7,false,false},strict{abc::TextEncodingKind::utf7,false,true};
void reference(const std::filesystem::path& path){Reader r(path);check(r.bytes(8)=="ABCUTF71","UTF7 header");check(r.text()=="System.Text.UTF7Encoding","Actual UTF7 runtime metadata");
 auto contexts=r.number();check(contexts==22,"Every encoder residual value and phase");
 for(unsigned k=0;k<contexts;++k){const auto prefix=r.result().first;const auto prefixBytes=r.bytes(r.byte());abc::TextEncoder encoder(normal),strictEncoder(strict);check(encoder.encode(prefix,false,{})==prefixBytes,"Encoder prefix");check(strictEncoder.encode(prefix,false,{})==prefixBytes,"Strict encoder prefix");
  for(unsigned n=0;n<65536;++n){const auto expected=r.bytes(r.byte());const auto input=std::u16string(1,static_cast<char16_t>(n));auto next=encoder;check(next.encode(input,true,{})==expected,"Every BMP encoder suffix");next=encoder;auto streamed=next.encode(input,false,{});streamed+=next.encode({},true,{});check(streamed==expected,"Encoder empty final split");auto exact=strictEncoder;check(exact.encode(input,true,{})==expected,"Every strict UTF16 unit");if(prefix.empty())check(abc::encode_text_bytes(input,normal,{})==expected,"Stateless BMP encoding");}
 }
 const auto scalars=r.number();check(scalars==1048576,"All supplementary scalars");for(unsigned n=0;n<scalars;++n){const auto expected=r.bytes(r.byte());std::u16string input;input+=static_cast<char16_t>(0xd800+(n>>10));input+=static_cast<char16_t>(0xdc00+(n&1023));check(abc::encode_text_bytes(input,normal,{})==expected,"All scalar pairs");abc::TextEncoder enc(normal);auto out=enc.encode(std::u16string_view(input).substr(0,1),false,{});out+=enc.encode(std::u16string_view(input).substr(1),true,{});check(out==expected,"Every surrogate split");check(abc::encode_text_bytes(input,strict,{})==expected,"Strict scalar pairs");}
 auto states=r.number();check(states==21847,"All decoder residual values, phases and ASCII/first-plus states");
 for(unsigned k=0;k<states;++k){const auto prefix=r.bytes(r.byte());const auto prefixValue=r.result().first;abc::TextDecoder decoder(normal,false),strictDecoder(strict,false);check(decoder.decode(prefix,false,{})==prefixValue,"Decoder prefix");check(strictDecoder.decode(prefix,false,{})==prefixValue,"Strict decoder prefix");
  for(unsigned n=0;n<256;++n){const auto [expected,exact]=r.result();const auto input=std::string(1,static_cast<char>(n));auto next=decoder;check(next.decode(input,true,{})==expected,"Every decoder residual/suffix");next=decoder;auto split=next.decode(input,false,{});split+=next.decode({},true,{});check(split==expected,"Decoder empty final split");next.resume_after_final();check(next.decode("A",true,{})==u"A","Decoder final resets bit state");
   try{auto s=strictDecoder;check(s.decode(input,true,{0,31,2})==expected&&exact,"Strict contextual decode");}catch(const abc::Error& e){check(!exact&&e.code=="E_ENCODING"&&!e.russian.empty()&&e.location.line==31,"Strict UTF7 fallback");}
  }
 }
 auto pairs=r.number();check(pairs==65536,"All fresh byte pairs");for(unsigned n=0;n<pairs;++n){const auto [expected,exact]=r.result();std::string input;input+=static_cast<char>(n>>8);input+=static_cast<char>(n);check(abc::decode_text_bytes(input,normal,false,{})==expected,"Stateless byte pairs");for(unsigned cut=0;cut<=2;++cut){abc::TextDecoder d(normal,false);auto actual=d.decode(std::string_view(input).substr(0,cut),false,{});actual+=d.decode(std::string_view(input).substr(cut),true,{});check(actual==expected,"Every pair split");}try{check(abc::decode_text_bytes(input,strict,false,{0,31,2})==expected&&exact,"Strict pair");}catch(const abc::Error& e){check(!exact&&e.code=="E_ENCODING"&&!e.russian.empty(),"Strict pair fallback");}}
 check(r.file.peek()==std::char_traits<char>::eof(),"All UTF7 reference consumed");
 const auto program=abc::compile("begin var name:=ReadlnString;var e:=Encoding.GetEncoding(name);Writeln(e.CodePage,' ',e.GetType.Name);Writeln(e=Encoding.GetEncoding(65000));Writeln(e.GetPreamble.Length);end.");std::ifstream aliases(std::filesystem::path(abc::from_utf8(__FILE__)).parent_path()/"fixtures/encoding-aliases-reference.tsv");std::string line;unsigned count=0;while(std::getline(aliases,line)){if(!line.empty()&&line.back()=='\r')line.pop_back();if(line.empty()||line[0]=='#')continue;const auto tab=line.find('\t');if(std::stoul(line.substr(tab+1))!=65000)continue;++count;auto name=line.substr(0,tab);for(unsigned variant=0;variant<2;++variant){std::istringstream input(name+"\n");std::ostringstream output;abc::execute(program,input,output);check(output.str()=="65000 UTF7Encoding\nTrue\n0\n","UTF7 aliases/case/cache/preamble");for(auto& ch:name)if(ch>='a'&&ch<='z')ch=static_cast<char>(ch-32);}}check(count==6,"All six UTF7 aliases");
 try{abc::encode_text_bytes(u"A"+std::u16string(393215,u'日'),normal,{0,31,2});check(false,"Missing final hyphen bound");}catch(const abc::Error& e){check(e.code=="E_LIMIT"&&!e.russian.empty()&&e.location.line==31,"Bilingual final-hyphen bound");}
 abc::TextEncoder retained(normal);check(retained.encode(u"日",false,{})=="+Ze","UTF7 emits before surrogate-style carry");try{retained.encode(std::u16string(393217,u'日'),true,{0,31,2});check(false,"Missing encoder bound");}catch(const abc::Error& e){check(e.code=="E_LIMIT","Rejected encoder size");}check(retained.encode({},true,{})=="U-","Rejected encode retains original residual bits");
}
std::string unhex(std::string_view value,bool utf16){if(value=="-")return {};std::string raw;std::u16string text;const auto width=utf16?4U:2U;for(std::size_t n=0;n<value.size();n+=width){auto v=std::stoul(std::string(value.substr(n,width)),nullptr,16);if(utf16)text+=static_cast<char16_t>(v);else raw+=static_cast<char>(v);}return utf16?abc::to_utf8(text,true):raw;}
void files(){struct Temporary{std::filesystem::path path=std::filesystem::temp_directory_path()/("ABC UTF7 "+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()));Temporary(){std::filesystem::create_directories(path);}~Temporary(){std::error_code e;std::filesystem::remove_all(path,e);}} temporary;const auto path=temporary.path/std::filesystem::path(u8"данные.txt");std::string literal;for(auto ch:path.generic_u8string()){literal+=static_cast<char>(ch);if(ch==u8'\'')literal+='\'';}
 const auto program=abc::compile("uses FilesOperations;var op:integer;begin Read(op);var e:=Encoding.GetEncoding(65000);DefaultEncoding:=e;var name:='"+literal+"';"
  "if op=0 then WriteStringToFile(name,'A'#13#10'日本語 + 中文 한국어 éＡ🌍'#0'Z'+#55357);if op=1 then Write(ReadAllText(name));if op=2 then Write(ReadFileToEnd(name));"
  "if op=3 then WriteStringToFile(name,StringOfChar('A',1023)+'日日'+StringOfChar('B',1024)+'+'+#55357);"
  "if op>=4 then begin var f:Text;Assign(f,name);Rewrite(f);if op=4 then begin Write(f,StringOfChar('A',1023)+'日'+#55357);Write(f,#56832+'日'+StringOfChar('B',1024)+'+'+#55357);end;"
  "if op=5 then begin Write(f,'日');Flush(f);Write(f,'日');end;if op=6 then begin Write(f,'日+');Flush(f);Write(f,'日+');end;if op=7 then Write(f,'日');"
  "if op=8 then begin Write(f,'日');DefaultEncoding:=Encoding.UTF8;Write(f,'A日');end;if op=9 then begin Write(f,StringOfChar('日',1025));Rewrite(f);Write(f,'日');end;"
  "if op=11 then begin Write(f,'日日日');Flush(f);Flush(f);Write(f,'+');end;if op=12 then begin Write(f,'日');Flush(f);Write(f,#55357);Flush(f);Write(f,#56832);end;Close(f);if op=7 then begin Append(f);Write(f,'日');Close(f);end;end;end.");
 const auto fixtures=std::filesystem::path(abc::from_utf8(__FILE__)).parent_path()/"fixtures";std::ifstream data(fixtures/"utf7-files-reference.tsv"),legacy(fixtures/"utf7-files-framework-reference.tsv");check(bool(data)&&bool(legacy),"Both UTF7 file corpora");std::string line,old;unsigned rows=0;while(std::getline(data,line)){if(!line.empty()&&line.back()=='\r')line.pop_back();if(line.empty()||line[0]=='#')continue;do{if(!std::getline(legacy,old))throw std::runtime_error("Truncated legacy file corpus");if(!old.empty()&&old.back()=='\r')old.pop_back();}while(old.empty()||old[0]=='#');check(line==old,"Framework and modern UTF7 file equality");const auto a=line.find('\t'),b=line.find('\t',a+1),c=line.find('\t',b+1);const auto op=std::stoi(line.substr(a+1,b-a-1));bool write=op==0||op>=3;
  if(write){std::error_code e;std::filesystem::remove(path,e);}else{std::ofstream file(path,std::ios::binary);auto raw=unhex(std::string_view(line).substr(b+1,c-b-1),false);file.write(raw.data(),raw.size());}std::istringstream input(std::to_string(op));std::ostringstream output;
  if(op==10){abc::TextFile file;file.filename=path;file.encoding=normal;file.encoder.emplace(normal);file.writer=std::make_shared<abc::FileWriter>(path,false,abc::SourceLocation{});abc::text_write(file,std::u16string(1025,u'日'),{});try{abc::text_write(file,std::u16string(1'048'500,u'A'),{0,31,2});check(false,"Missing writer preview limit");}catch(const abc::Error& e){check(e.code=="E_LIMIT"&&!e.russian.empty()&&e.location.line==31,"Rejected UTF7 preview");}file.close({});}else abc::execute(program,input,output);
  auto expected=unhex(std::string_view(line).substr(c+1),!write);if(!write){std::u16string exactExpected;auto hex=std::string_view(line).substr(c+1);if(hex!="-")for(std::size_t n=0;n<hex.size();n+=4)exactExpected+=static_cast<char16_t>(std::stoul(std::string(hex.substr(n,4)),nullptr,16));abc::LineReader reader(path,normal,{});std::u16string exactActual;if(op==1)exactActual=reader.read_to_end({},{});else while(auto next=reader.read_line({},{})){exactActual+=*next;exactActual+=u'\n';}check(exactActual==exactExpected,"File reader preserves raw UTF16 including lone surrogates");}if(write){std::ifstream file(path,std::ios::binary);std::ostringstream raw;raw<<file.rdbuf();check(output.str().empty()&&raw.str()==expected,"UTF7 buffered/Flush/Rewrite write row "+std::to_string(rows));}else{auto actual=output.str();if(op==2)for(std::size_t n=0;(n=actual.find("\r\n",n))!=actual.npos;)actual.erase(n,1);check(actual==expected,"UTF7 read/BOM/EOF row "+std::to_string(rows));}++rows;
 }check(rows==1421,"All UTF7 file recipes");}
}
int main(int argc,char** argv){try{if(argc!=2)throw std::runtime_error("Pass unpacked UTF7 reference");reference(std::filesystem::path(argv[1]));files();}catch(const std::exception& e){check(false,e.what());}std::cout<<checks<<" UTF7 checks, "<<failures<<" failures\n";return failures?1:0;}